import os
import hashlib
import hmac
import unicodedata
import re
import secrets
from pathlib import PurePosixPath
from functools import lru_cache

# Secure file serving application with strict path validation

BASE_DIR = '/var/www/static'
ALLOWED_EXTENSIONS = {'.html', '.css', '.js', '.png', '.jpg', '.gif', '.svg', '.woff2'}
MAX_PATH_LENGTH = 256
MAX_FILE_SIZE = 10 * 1024 * 1024  # 10MB

class SecurityError(Exception):
    pass

class RateLimiter:
    def __init__(self, max_requests=100, window=60):
        self._requests = {}
        self._max = max_requests
        self._window = window

    def check(self, client_ip):
        import time
        now = time.time()
        if client_ip not in self._requests:
            self._requests[client_ip] = []
        self._requests[client_ip] = [
            t for t in self._requests[client_ip] if now - t < self._window
        ]
        if len(self._requests[client_ip]) >= self._max:
            return False
        self._requests[client_ip].append(now)
        return True

rate_limiter = RateLimiter()

def generate_csrf_token():
    return secrets.token_hex(32)

def validate_csrf(token, expected):
    if not token or not expected:
        return False
    return hmac.compare_digest(token.encode(), expected.encode())

def sanitize_path_component(component):
    """Remove dangerous characters from a single path component."""
    # Block null bytes
    if '\x00' in component:
        raise SecurityError("Null byte in path")
    # Block path traversal sequences
    if component in ('.', '..') or component.startswith('..'):
        raise SecurityError("Path traversal attempt")
    # Only allow alphanumeric, dash, underscore, dot
    if not re.match(r'^[a-zA-Z0-9_\-\.]+$', component):
        raise SecurityError(f"Invalid characters in path component: {component}")
    return component

def validate_extension(filename):
    """Check file extension against allowlist."""
    _, ext = os.path.splitext(filename)
    if ext.lower() not in ALLOWED_EXTENSIONS:
        raise SecurityError(f"Disallowed file extension: {ext}")
    return True

def normalize_path(user_input):
    """Normalize unicode in path to prevent homoglyph attacks."""
    # First validate the raw input for traversal
    if '..' in user_input or user_input.startswith('/'):
        raise SecurityError("Path traversal detected")

    # Validate each component of the raw path
    components = user_input.split('/')
    for comp in components:
        if comp:  # skip empty components from leading/trailing slashes
            sanitize_path_component(comp)

    # Now normalize unicode (NFKC normalization for consistency)
    normalized = unicodedata.normalize('NFKC', user_input)

    return normalized

def resolve_file_path(user_path):
    """Safely resolve a user-provided path to a file within BASE_DIR."""
    if not user_path or len(user_path) > MAX_PATH_LENGTH:
        raise SecurityError("Invalid path length")

    # Normalize the path (unicode + sanitization)
    clean_path = normalize_path(user_path)

    # Build the full path
    full_path = os.path.join(BASE_DIR, clean_path)

    # Resolve to absolute and verify it's within BASE_DIR
    resolved = os.path.realpath(full_path)
    if not resolved.startswith(BASE_DIR + '/'):
        raise SecurityError("Path escapes base directory")

    # Validate extension
    validate_extension(resolved)

    return resolved

def serve_file(client_ip, user_path, csrf_token=None, expected_csrf=None):
    """Main entry point for serving static files."""
    # Rate limiting
    if not rate_limiter.check(client_ip):
        return {'status': 429, 'body': 'Rate limited'}

    try:
        file_path = resolve_file_path(user_path)

        # Check file exists and size
        if not os.path.isfile(file_path):
            return {'status': 404, 'body': 'Not found'}

        file_size = os.path.getsize(file_path)
        if file_size > MAX_FILE_SIZE:
            return {'status': 413, 'body': 'File too large'}

        with open(file_path, 'rb') as f:
            content = f.read()

        # Generate ETag for caching
        etag = hashlib.sha256(content).hexdigest()[:16]

        return {
            'status': 200,
            'body': content,
            'headers': {
                'ETag': etag,
                'X-Content-Type-Options': 'nosniff',
                'Cache-Control': 'public, max-age=3600'
            }
        }
    except SecurityError as e:
        return {'status': 403, 'body': f'Forbidden: {e}'}
    except (OSError, IOError):
        return {'status': 500, 'body': 'Internal error'}
